 UIElement OverlaySettings(){var p=new StackPanel{Margin=new Thickness(8)};p.Children.Add(Ui.Label("Show these entries in the Overlays context submenu",12));foreach(string name in OverlayNames33)Ui.Check(p,name,!Config.HiddenOverlays.Contains(name),v=>{Config.HiddenOverlays.Remove(name);if(!v)Config.HiddenOverlays.Add(name);});return p;}
 void SetupRound31(){if(!Config.Keys.ContainsKey("Slideshow toggle"))Config.Keys["Slideshow toggle"]=new[]{"Y"};if(!Config.Keys.ContainsKey("Filmstrip"))Config.Keys["Filmstrip"]=new[]{"G"};if(!Config.Keys.ContainsKey("Grayscale view"))Config.Keys["Grayscale view"]=new[]{"I"};if(!Config.Effects31){if(Config.SlideEffect=="Slow Zoom")Config.SlideViews=new(){"Zoom In","Zoom Out"};else if(Config.SlideEffect is "Pan with Blurred Background" or "Random"){Config.SlideBackgrounds=new(){"Blur"};Config.SlideViews=Config.SlideEffect=="Random"?new(){"Pan","Zoom In","Zoom Out"}:new(){"Pan"};}Config.Effects31=true;}histogramPanel=new Border{Width=280,Height=135,Background=new SolidColorBrush(Color.FromArgb(192,30,32,36)),CornerRadius=new(6),Padding=new(8),HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Top,Margin=new(12,180,12,12),Visibility=Visibility.Collapsed};histogramPanel.MouseRightButtonUp+=(_,e)=>{HistogramMenu33().IsOpen=true;e.Handled=true;};root.Children.Add(histogramPanel);}
 bool Round31Key(string key){if(Mode!="viewer"||Quick)return false;if(Config.Keys["Slideshow toggle"].Contains(key)){SlideshowKey33();return true;}if(Config.Keys["Filmstrip"].Contains(key)){Config.Filmstrip=!Config.Filmstrip;ResetFilmstrip();Config.Save();return true;}if(Config.Keys["Grayscale view"].Contains(key)){Config.Grayscale=!Config.Grayscale;graySource=null;grayImage=null;grayEpoch++;Config.Save();View.InvalidateVisual();return true;}return false;}
 public BitmapSource DisplayImage(BitmapSource image){if(!Config.Grayscale||Cropping||currentMotion)return image;if(ReferenceEquals(graySource,image)&&grayImage!=null)return grayImage;if(!grayPending){grayPending=true;int token=grayEpoch;_=Task.Run(async()=>{try{var result=await Sta.Run(()=>{return PixelAnalysis.Grayscale(image);});await Dispatcher.InvokeAsync(()=>{if(token==grayEpoch&&ReferenceEquals(View.Image,image)){graySource=image;grayImage=result;View.InvalidateVisual();}});}finally{await Dispatcher.InvokeAsync(()=>{grayPending=false;View.InvalidateVisual();});}});}return image;}
 async void RefreshHistogram(){histogramPanel.Visibility=Config.Histogram&&Mode=="viewer"&&!currentMotion&&View.Image!=null?Visibility.Visible:Visibility.Collapsed;if(histogramPending||histogramPanel.Visibility!=Visibility.Visible||ReferenceEquals(histogramImage,View.Image))return;histogramPending=true;var source=View.Image!;histogramImage=source;int token=++histogramEpoch;try{var counts=await LoaderPool.Run(()=>PixelAnalysis.Histogram(source));if(token!=histogramEpoch||!ReferenceEquals(View.Image,source))return;histogramPanel.Child=new HistogramDrawing(counts,Config.HistogramRed,Config.HistogramGreen,Config.HistogramBlue,Config.HistogramGray);}catch(Exception e){Paths.Log("histogram",e.Message);}finally{histogramPending=false;}}
