 void ResizeImageWindow(double factor,bool match){if(!imageWindow||View.Image==null)return;if(Config.BorderlessFitsWindow){ResizeFixedWindow36(factor);return;}var screen=System.Windows.Forms.Screen.FromHandle(new System.Windows.Interop.WindowInteropHelper(this).Handle).WorkingArea;var dpi=VisualTreeHelper.GetDpi(this);var bounds=new Rect(screen.Left/dpi.DpiScaleX,screen.Top/dpi.DpiScaleY,screen.Width/dpi.DpiScaleX,screen.Height/dpi.DpiScaleY);double area=match?(imageWindowArea>0?imageWindowArea:Width*Height):Width*Height*factor*factor;var r=WindowSizing32.Resize(new Rect(Left,Top,Width,Height),area,View.Image.PixelWidth/(double)View.Image.PixelHeight,bounds);ApplyImageWindow33(r,dpi.DpiScaleX,dpi.DpiScaleY);if(!match)imageWindowArea=r.Width*r.Height;}

