public static class PixelAnalysis {
 public static byte[] Pixels(BitmapSource source,out int stride){var b=new FormatConvertedBitmap(source,PixelFormats.Bgra32,null,0);stride=source.PixelWidth*4;var data=new byte[stride*source.PixelHeight];b.CopyPixels(data,stride,0);return data;}
 public static BitmapSource Grayscale(BitmapSource source){var bytes=Pixels(source,out int stride);for(int p=0;p<bytes.Length;p+=4){byte luminance=(byte)Math.Round(.2126*bytes[p+2]+.7152*bytes[p+1]+.0722*bytes[p]);bytes[p]=bytes[p+1]=bytes[p+2]=luminance;}var image=BitmapSource.Create(source.PixelWidth,source.PixelHeight,source.DpiX,source.DpiY,PixelFormats.Bgra32,null,bytes,stride);image.Freeze();return image;}
 public static long[][] Histogram(BitmapSource source){var data=Pixels(source,out _);var bins=Enumerable.Range(0,4).Select(_=>new long[256]).ToArray();for(int p=0;p<data.Length;p+=4){if(data[p+3]==0)continue;bins[0][data[p+2]]++;bins[1][data[p+1]]++;bins[2][data[p]]++;bins[3][(int)Math.Round(.2126*data[p+2]+.7152*data[p+1]+.0722*data[p])]++;}return bins;}
}
sealed class HistogramDrawing:FrameworkElement {
 readonly long[][] bins;readonly bool[] enabled;public HistogramDrawing(long[][] b,params bool[] e){bins=b;enabled=e;}
 protected override void OnRender(DrawingContext dc){var colors=new[]{Colors.IndianRed,Colors.LightGreen,Colors.CornflowerBlue,Colors.Gainsboro};long peak=bins.Where((_,i)=>enabled[i]).SelectMany(b=>b).DefaultIfEmpty(1).Max();for(int i=0;i<4;i++){if(!enabled[i])continue;var g=new StreamGeometry();using(var c=g.Open()){c.BeginFigure(new Point(0,ActualHeight),false,false);for(int x=0;x<256;x++)c.LineTo(new Point(x/255d*ActualWidth,ActualHeight-bins[i][x]/(double)Math.Max(1,peak)*(ActualHeight-4)),true,false);}g.Freeze();dc.DrawGeometry(null,new Pen(new SolidColorBrush(colors[i]),1),g);}}
}
